(()=>{'use strict';
const C={ink:'#163d55',active:'#267a81',light:'#e4f1ee',warm:'#bc7137',muted:'#a5b8bd'};
const copy=x=>JSON.parse(JSON.stringify(x));
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fact=n=>{let a=1;for(let i=2;i<=n;i++)a*=i;return a;};
const binom=(n,k)=>k<0||k>n?0:fact(n)/(fact(k)*fact(n-k));
function partitions(n,hi=n){if(n===0)return[[]];let a=[];for(let j=Math.min(n,hi);j>=1;j--)for(const p of partitions(n-j,j))a.push([j,...p]);return a;}
function compositions(n){if(n===0)return[[]];let a=[];for(const j of[1,2])if(j<=n)for(const p of compositions(n-j))a.push([j,...p]);return a;}
function dyck(n){const a=[];function f(s,u,d){if(u===n&&d===n){a.push(s);return;}if(u<n)f(s+'U',u+1,d);if(d<u)f(s+'D',u,d+1);}f('',0,0);return a;}
const operations=['inverse','convolution','filter','bounded','coins','composition','partitions','durfee','catalan','labelled','marking','poles'];
function validate(raw){const s={operation:raw.operation,n:Number(raw.n??5)};if(s.operation==='convolution')s.base=Number(raw.base??2);if(s.operation==='filter')s.residue=Number(raw.residue??1);if(s.operation==='bounded')s.boxes=Number(raw.boxes??3);if(s.operation==='coins')s.weights=raw.weights??[1,2,3];if(!operations.includes(s.operation))throw Error('Choose one of the declared exact models.');if(!Number.isInteger(s.n)||s.n<1||s.n>10)throw Error('The target must be an integer from one through ten.');if(s.operation==='convolution'&&s.n>6)throw Error('The convolution grid supports target indices through six.');if(['composition','durfee'].includes(s.operation)&&s.n>7)throw Error('Complete object enumeration supports sizes through seven.');if(['labelled','marking'].includes(s.operation)&&s.n>6)throw Error('Complete label or binary-word enumeration supports sizes through six.');if(s.operation==='catalan'&&s.n>4)throw Error('Complete Dyck enumeration supports at most four pairs.');if(s.base!==undefined&&![2,3].includes(s.base))throw Error('The convolution base is two or three.');if(s.residue!==undefined&&![0,1,2].includes(s.residue))throw Error('A residue modulo three is zero, one or two.');if(s.boxes!==undefined&&![3,4].includes(s.boxes))throw Error('Use three or four capped boxes.');if(s.operation==='bounded'&&s.n>3*s.boxes)throw Error('The total exceeds the sum of the box caps.');if(s.weights!==undefined&&![[1,2,3],[1,2,5]].some(a=>JSON.stringify(a)===JSON.stringify(s.weights)))throw Error('The declared coin inventories are one/two/three or one/two/five.');return s;}
function evaluate(raw){const s=validate(raw),n=s.n,states=[];let result;
 if(s.operation==='inverse'){let a=[];for(let k=0;k<=n;k++){a.push(k===0?1:2*a[k-1]+(a[k-2]??0));states.push({step:k,values:a.slice(),value:a[k]});}result={coefficient:a[n],coefficients:a,denominator:[1,-2,-1]};}
 else if(s.operation==='convolution'){let total=0;for(let k=0;k<=n;k++){const term=(k+1)*s.base**(n-k);total+=term;states.push({step:k,i:k,j:n-k,term,total});}result={coefficient:total,a:Array.from({length:n+1},(_,i)=>i+1),b:Array.from({length:n+1},(_,i)=>s.base**i)};}
 else if(s.operation==='filter'){let retained=[];for(let k=0;k<=n;k++){const keep=k%3===s.residue;if(keep)retained.push({index:k,value:2**k});states.push({step:k,keep,value:2**k,retained:copy(retained)});}result={retained,modulus:3,residue:s.residue};}
 else if(['bounded','coins','partitions'].includes(s.operation)){let row=[1,...Array(n).fill(0)];states.push({step:0,rows:[row.slice()],factor:0});const rows=[row.slice()];const factors=s.operation==='bounded'?Array(s.boxes).fill(1):s.operation==='coins'?s.weights:Array.from({length:n},(_,i)=>i+1);factors.forEach((w,i)=>{const next=Array(n+1).fill(0);for(let t=0;t<=n;t++)for(let q=0;q*w<=t;q++){if(s.operation==='bounded'&&q>3)break;next[t]+=row[t-q*w];}row=next;rows.push(row.slice());states.push({step:i+1,rows:copy(rows),factor:w,value:row[n]});});result={coefficient:row[n],coefficients:row,factors};if(s.operation==='bounded')result.objects=Array.from({length:4**s.boxes},(_,m)=>Array.from({length:s.boxes},(_,j)=>Math.floor(m/4**j)%4)).filter(p=>p.reduce((a,b)=>a+b,0)===n);if(s.operation==='partitions')result.objects=partitions(n);}
 else if(s.operation==='composition'){const objects=compositions(n);states.push({step:0,parts:[],count:objects.length});objects.forEach((p,i)=>states.push({step:i+1,parts:p,count:objects.length}));result={coefficient:objects.length,objects};}
 else if(s.operation==='durfee'){const objects=partitions(n);objects.forEach((p,i)=>{let d=0;while(p[d]>d)d++;states.push({step:i+1,parts:p,d,arm:p.slice(0,d).map(a=>a-d),leg:p.slice(d)});});result={coefficient:objects.length,objects,durfeeCounts:objects.reduce((a,p)=>{let d=0;while(p[d]>d)d++;a[d]=(a[d]??0)+1;return a;},{})};}
 else if(s.operation==='catalan'){const paths=dyck(n);states.push({step:0,path:'',split:0});paths.forEach((path,i)=>{let h=0,split=0;for(let j=0;j<path.length;j++){h+=path[j]==='U'?1:-1;if(h===0&&!split)split=j+1;}states.push({step:i+1,path,split});});result={coefficient:paths.length,paths};}
 else if(s.operation==='labelled'){for(let mask=0;mask<2**n;mask++){let left=[],right=[];for(let i=0;i<n;i++)((mask>>i)&1?left:right).push(i+1);states.push({step:mask+1,left,right,k:left.length,multiplicity:binom(n,left.length)});}result={count:2**n,byLeftSize:Array.from({length:n+1},(_,k)=>binom(n,k))};}
 else if(s.operation==='marking'){let histogram=Array(n+1).fill(0),total=0;for(let mask=0;mask<2**n;mask++){const word=mask.toString(2).padStart(n,'0');const ones=[...word].filter(c=>c==='1').length;histogram[ones]++;total+=ones;states.push({step:mask+1,word,ones,histogram:histogram.slice(),total});}result={count:2**n,total,mean:n/2,histogram};}
 else {for(let k=0;k<=n;k++)states.push({step:k,value:binom(k+2,2)*2**k,weight:binom(k+2,2),base:2**k});result={coefficient:binom(n+2,2)*2**n,coefficients:states.map(z=>z.value),pole:0.5,multiplicity:3};}
 return{spec:s,states,result};}
function txt(x,y,t,math=false,anchor='start'){return `<text x="${x}" y="${y}" class="gf-${math?'math':'prose'}" text-anchor="${anchor}">${esc(t)}</text>`;}
function rect(x,y,w,h,fill=C.light){return `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="6" fill="${fill}" stroke="${C.muted}"/>`;}
function circle(x,y,t,fill=C.light){return `<circle cx="${x}" cy="${y}" r="22" fill="${fill}" stroke="${C.muted}"/>`+txt(x,y+6,t,true,'middle');}
function svg(b,h=350){return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 760 '+h+'" role="img" aria-label="Exact generating-function checkpoint"><rect x="1" y="1" width="758" height="'+(h-2)+'" rx="10" fill="white" stroke="#d7e4e8"/>'+b+'</svg>';}
function row(values,y,active=-1,indices=true){let b='';const w=Math.min(60,660/values.length);values.forEach((v,i)=>{const x=82+i*w;b+=rect(x,y,w-8,44,i===active?'#f8e4d3':C.light)+txt(x+(w-8)/2,y+29,v,true,'middle');if(indices)b+=txt(x+(w-8)/2,y-12,i,true,'middle');});return b;}
function ferrers(parts,x,y,d=0){let b='';const cell=27;parts.forEach((n,r)=>{for(let c=0;c<n;c++)b+=rect(x+c*cell,y+r*cell,22,22,r<d&&c<d?'#f8e4d3':r<d?'#dce9f4':C.light);});return b;}
function draw(s,z,r){const n=s.n;let b='';
 if(s.operation==='inverse'){b+=txt(30,36,'Build the reciprocal one coefficient at a time')+txt(30,78,'Denominator coefficients: 1, −2, −1',true)+row(z.values,143,z.step)+txt(30,259,z.step?'Cancel degree '+z.step+': b = 2 × preceding + two-back':'The constant product is one: b at zero equals one')+txt(30,307,'Current coefficient: '+z.value,true);}
 else if(s.operation==='convolution'){b+=txt(28,36,'Choose only exponent pairs whose sum is '+n);const cell=38,x0=155,y0=90;for(let i=0;i<=n;i++){b+=txt(x0-25,y0+i*cell+25,i,true,'middle')+txt(x0+i*cell+18,y0-20,i,true,'middle');for(let j=0;j<=n;j++){const active=i===z.i&&j===z.j,diag=i+j===n;b+=rect(x0+j*cell,y0+i*cell,36,36,active?'#f8e4d3':diag?C.light:'#f5f8f9');if(diag)b+=txt(x0+j*cell+18,y0+i*cell+25,(i+1)*s.base**j,true,'middle');}}b+=txt(470,106,'Row exponent: '+z.i,true)+txt(470,150,'Column exponent: '+z.j,true)+txt(470,194,'Add product: '+z.term,true)+txt(470,238,'Sum so far: '+z.total,true)+txt(470,286,'Other diagonals contribute')+txt(470,318,'to other target coefficients.');}
 else if(s.operation==='filter'){b+=txt(30,36,'Keep indices with residue '+s.residue+' modulo three');const values=Array.from({length:n+1},(_,i)=>2**i);b+=row(values,140,z.step);const w=Math.min(60,660/values.length);for(let i=0;i<=n;i++)if(i%3===s.residue)b+=`<line x1="${82+i*w}" x2="${82+i*w+w-8}" y1="194" y2="194" stroke="${C.active}" stroke-width="4"/>`;b+=txt(30,257,'Current index '+z.step+': '+(z.keep?'retain this coefficient':'suppress this coefficient'))+txt(30,307,'Filtered size indices: '+z.retained.map(t=>t.index).join(', '),true);}
 else if(['bounded','coins','partitions'].includes(s.operation)){const title=s.operation==='bounded'?s.boxes+' boxes: each multiplicity is zero through three':s.operation==='coins'?'Unordered change: denominations '+s.weights.join(', '):'Integer partitions: add one allowed part size at a time';b+=txt(30,36,title);const shown=z.rows.length>4?z.rows.slice(-4):z.rows,start=z.rows.length-shown.length;shown.forEach((a,i)=>{b+=txt(14,105+i*57,'Row '+(start+i),false)+row(a,78+i*57,n,i===0);});b+=txt(30,317,'Factors processed: '+z.step+'; target count: '+z.rows.at(-1)[n],true);}
 else if(s.operation==='composition'){b+=txt(30,36,'Ordered parts one or two: every complete composition');const w=620/n;let total=0;for(const p of z.parts){const x=65+total*w;b+=rect(x,114,p*w-12,74,p===2?'#dce9f4':C.light)+txt(x+(p*w-12)/2,160,p,true,'middle');total+=p;}for(let i=0;i<=n;i++)b+=txt(65+i*w,235,i,true,'middle');b+=txt(30,295,z.step?'Composition '+z.step+' of '+r.coefficient+': '+z.parts.join(' + '):'No components placed; next checkpoints enumerate complete objects',z.step>0);}
 else if(s.operation==='durfee'){b+=txt(30,34,'Durfee square, independent arm, and independent leg');b+=ferrers(z.parts,55, seventy(),z.d);b+=txt(370,95,'Square side: '+z.d,true)+txt(370,143,'Square cells: '+z.d*z.d,true)+txt(370,191,'Arm rows: '+z.arm.join(', '),true)+txt(370,239,'Leg rows: '+(z.leg.join(', ')||'none'),true)+txt(30,320,'Partition '+z.step+' of '+r.coefficient+'; total cells remain '+n);}
 else if(s.operation==='catalan'){b+=txt(30,35,'A first return separates the enclosed word and the suffix');const base=265,w=620/(2*n);let x=65,y=base,points=[[x,y]];b+=`<line x1="45" x2="715" y1="${base}" y2="${base}" stroke="${C.muted}"/>`;for(let i=0;i<z.path.length;i++){const nx=x+w,ny=y+(z.path[i]==='U'?-38:38);b+=`<line x1="${x}" y1="${y}" x2="${nx}" y2="${ny}" stroke="${i<z.split?C.warm:C.active}" stroke-width="3"/>`;x=nx;y=ny;points.push([x,y]);}for(const[x,y]of points)b+=`<circle cx="${x}" cy="${y}" r="4" fill="${C.ink}"/>`;b+=txt(30,320,z.step?'First-return step '+z.split+'; enclosed pairs '+(z.split/2-1):'Empty axes before listing all '+r.coefficient+' valid paths');}
 else if(s.operation==='labelled'){b+=txt(30,36,'Two named recipients: allocate every distinct label once')+rect(40,92,320,134)+rect(400,92,320,134)+txt(65,126,'Recipient A')+txt(425,126,'Recipient B');z.left.forEach((i,j)=>b+=circle(70+j*48,177,i));z.right.forEach((i,j)=>b+=circle(430+j*48,177,i));b+=txt(30,272,'Allocation '+z.step+' of '+r.count+'; labels sent to A: '+z.k)+txt(30,320,'This size split has '+z.multiplicity+' distinct label allocations.');}
 else if(s.operation==='marking'){b+=txt(30,36,'Enumerate binary words and accumulate the marked statistic');[...z.word].forEach((ch,i)=>b+=rect(60+i*94,92, seventy(), sixty(),ch==='1'?'#f8e4d3':C.light)+txt(95+i*94,130,ch,true,'middle'));b+=txt(30,200,'Ones in this word: '+z.ones,true)+txt(30,244,'Words counted: '+z.step+'; accumulated ones: '+z.total,true)+txt(30,292,'Final total / final word count: '+r.total+' / '+r.count+' = '+r.mean,true);}
 else {b+=txt(30,36,'A third-order pole creates a quadratic binomial weight')+rect(40,88,200,92)+txt(140,123,'Index '+z.step,true,'middle')+txt(140,155,'Weight '+z.weight,true,'middle')+txt(260,139,'×',true,'middle')+rect(290,88,180,92)+txt(380,123,'Base power',false,'middle')+txt(380,155,z.base,true,'middle')+txt(500,139,'=',true,'middle')+rect(530,88,185,92)+txt(622,123,'Coefficient',false,'middle')+txt(622,155,z.value,true,'middle')+txt(30,254,'Pole location one-half; surviving multiplicity three.')+txt(30,306,'The polynomial is (n + 2)(n + 1) / 2.',true);}
 return svg(b,s.operation==='convolution'?380:350);}
function seventy(){return 70;}function sixty(){return 60;}
const why={inverse:'The constant term fixes the reciprocal boundary, then each coefficient equation cancels exactly.',convolution:'Only the target diagonal contributes; every term multiplies independent choices of complementary sizes.',filter:'Filtering keeps original indices and suppresses every coefficient in the other residue classes.',bounded:'Each new box contributes exactly one multiplicity from zero through three to the additive total.',coins:'Each denomination is a new independent multiplicity; permutations of identical coins are not counted.',composition:'Each bar width is a positive part, and the left-to-right order distinguishes compositions.',partitions:'A product over part sizes chooses one unordered multiplicity vector for every integer partition.',durfee:'The maximal square is unique, and its arm and leg form independent bounded partitions.',catalan:'Every valid path has one first return, giving a unique enclosed/suffix decomposition.',labelled:'Each labelled product chooses which labels go to each named recipient, producing binomial allocation factors.',marking:'Marking counts actual ones; summing over all equiprobable words gives the mean only after normalization.',poles:'A repeated inverse factor combines a polynomial binomial weight with the exponential base reciprocal to its pole.'};
function formula(s,z,r){if(s.operation==='inverse')return 'b_{'+z.step+'}='+z.value;if(s.operation==='convolution')return '[x^{'+s.n+'}]A(x)B(x)='+r.coefficient;if(s.operation==='filter')return 'n\\equiv'+s.residue+'\\pmod3';if(['bounded','coins','partitions'].includes(s.operation))return '[x^{'+s.n+'}]P_{'+z.step+'}(x)='+z.rows.at(-1)[s.n];if(s.operation==='composition')return '[x^{'+s.n+'}]\\frac{1}{1-x-x^2}='+r.coefficient;if(s.operation==='durfee')return 'd='+z.d+',\\quad n='+s.n;if(s.operation==='catalan')return 'C_{'+s.n+'}=\\frac{1}{'+(s.n+1)+'}\\binom{'+2*s.n+'}{'+s.n+'}='+r.coefficient;if(s.operation==='labelled')return '\\binom{'+s.n+'}{'+z.k+'}='+z.multiplicity;if(s.operation==='marking')return 'E[X]=\\frac{'+r.total+'}{'+r.count+'}='+r.mean;return 'a_{'+z.step+'}=\\binom{'+(z.step+2)+'}{2}2^{'+z.step+'}='+z.value;}
function stateMath(s,z,r){const num=v=>'<mn>'+esc(v)+'</mn>',id=v=>'<mi>'+v+'</mi>',sub=(v,k)=>'<msub>'+id(v)+num(k)+'</msub>',equal=(a,b)=>a+'<mo>=</mo>'+num(b);let body;
 if(s.operation==='inverse')body=equal(sub('b',z.step),z.value);
 else if(s.operation==='convolution')body=equal(sub('S',z.step),z.total);
 else if(s.operation==='filter')body=equal(sub('a',z.step),z.value)+'<mtext>'+ (z.keep?' retained':' suppressed')+'</mtext>';
 else if(['bounded','coins','partitions'].includes(s.operation))body=equal('<mo>[</mo><msup>'+id('x')+num(s.n)+'</msup><mo>]</mo>'+sub('P',z.step),z.rows.at(-1)[s.n]);
 else if(s.operation==='durfee')body=equal(id('d'),z.d)+'<mo>,</mo>'+equal(id('n'),s.n);
 else if(s.operation==='marking')body=equal(sub('S',z.step),z.total);
 else if(s.operation==='labelled')body=equal(id('k'),z.k)+'<mo>,</mo>'+equal(id('N'),z.multiplicity);
 else if(s.operation==='poles')body=equal(sub('a',z.step),z.value);
 else body=equal(id('N'),r.coefficient);
 return '<math xmlns="http://www.w3.org/1998/Math/MathML"><mrow>'+body+'</mrow></math>';}

function action(s,z){if(s.operation==='convolution')return 'Add the product at row '+z.i+' and column '+z.j+', equal to '+z.term+'.';if(s.operation==='labelled')return 'Assign the displayed label subset to recipient A and its complement to recipient B.';if(s.operation==='marking')return 'Inspect word '+z.word+', count '+z.ones+' ones, and add them to the cumulative statistic.';if(s.operation==='durfee')return 'Locate the largest square of side '+z.d+' and separate its arm and leg.';if(s.operation==='composition')return z.step?'Read the ordered part sequence '+z.parts.join(', ')+', whose sum is '+s.n+'.':'Begin complete enumeration; no part has yet been placed.';if(s.operation==='catalan')return z.step?'Locate the first return at step '+z.split+' and separate its two smaller balanced paths.':'Begin complete path enumeration from the baseline.';if(s.operation==='filter')return 'At original index '+z.step+', '+(z.keep?'retain':'suppress')+' coefficient '+z.value+'.';if(['bounded','coins','partitions'].includes(s.operation))return z.step?'Convolve the preceding row with the new allowed-multiplicity factor.':'Initialize the unique empty choice at total zero.';if(s.operation==='inverse')return z.step?'Solve the next coefficient equation from the two preceding inverse coefficients.':'Fix the constant inverse coefficient from the constant product one.';return 'Multiply the binomial weight '+z.weight+' by the exponential factor '+z.base+'.';}
function teachingCheck(s,z){const op=s.operation;const names={inverse:'Constant inverse coefficient',convolution:'Selected exponent sum',filter:'Retained residue modulo three',bounded:'Maximum per box',coins:'Current denomination',composition:'Allowed positive part sizes',partitions:'Largest processed part size',durfee:'Square plus arm plus leg',catalan:'Declared number of pairs',labelled:'Labels used exactly once',marking:'Binary word length',poles:'Surviving pole multiplicity'};let value;if(op==='inverse')value=1;else if(op==='convolution')value=z.i+z.j;else if(op==='filter')value=s.residue;else if(op==='bounded')value=3;else if(op==='coins')value=z.factor;else if(op==='composition')value='one or two';else if(op==='partitions')value=z.factor;else if(op==='durfee')value=z.d*z.d+z.arm.reduce((a,b)=>a+b,0)+z.leg.reduce((a,b)=>a+b,0);else if(op==='catalan')value=s.n;else if(op==='labelled')value=z.left.length+z.right.length;else if(op==='marking')value=z.word.length;else value=3;return[{mathHtml:names[op],result:String(value)}];}
function makeModel(id,title,raw){const{spec:s,states,result:r}=evaluate(raw);return{id,title,kind:'exact-discrete',spec:s,result:r,invariant:why[s.operation],frames:states.map((z,i)=>({svg:draw(s,z,r),caption:'Checkpoint '+(i+1)+' of '+states.length,formula:formula(s,z,r),formulaHtml:stateMath(s,z,r),snapshot:{step:i+1,state:copy(z),inputs:copy(s),result:i===states.length-1?copy(r):null},teaching:{currentState:'Declared model '+s.operation+', checkpoint '+(i+1),operation:action(s,z),why:why[s.operation],reading:'Compare neighboring exact checkpoints. Enumeration displays different complete objects, not a continuous evolution.',checks:teachingCheck(s,z)}}))};}
if(typeof module!=='undefined')module.exports={validate,evaluate,makeModel,partitions,compositions,dyck,binom,fact};
if(typeof document==='undefined')return;
function mount(host,m){if(!host.querySelector('.gf-controls')){const c=document.createElement('div');c.className='gf-controls';c.innerHTML='<button type="button" data-reset>Restart</button><button type="button" data-prev>Previous</button><button type="button" data-play>Play</button><button type="button" data-next>Next</button><label>Speed<select data-speed></select></label><label>Step<input type="range" data-seek min="0" value="0"></label>';host.querySelector('.gf-stage').before(c);}for(const cls of['gf-caption','gf-formula','gf-print'])if(!host.querySelector('.'+cls)){const e=document.createElement('div');e.className=cls;host.append(e);}return AdvancedSimulations.mount(host,m,{topic:'d_generating',prefix:'gf',retainDrawing:true});}
async function boot(){const data=await(await fetch('d_generating-models.json')).json();globalThis.GeneratingPlayers=[];for(const host of document.querySelectorAll('[data-gf-model]')){const m=data.models.find(m=>m.id===host.dataset.gfModel);if(!m)throw Error('Missing generating-function model');GeneratingPlayers.push(mount(host,m));}let active;const f=document.querySelector('#gf-form'),out=document.querySelector('#gf-output'),error=document.querySelector('#gf-error');f.addEventListener('submit',ev=>{ev.preventDefault();try{const m=makeModel('editable-generating','Your exact generating-function model',{operation:f.elements.operation.value,n:Number(f.elements.n.value)});active?.dispose();out.innerHTML='<section class="gf-model"><h3>'+esc(m.title)+'</h3><div class="gf-stage"></div></section><h3>Exact result</h3><pre>'+esc(JSON.stringify(m.result,null,2))+'</pre>';active=mount(out.firstChild,m);globalThis.GeneratingLab=active;error.textContent='';}catch(e){error.textContent=e.message;}});f.dispatchEvent(new Event('submit',{cancelable:true}));}
boot().catch(e=>{document.querySelector('#gf-error').textContent=e.message;throw e;});
})();
